import {relicFrame} from './relic-art.mjs';
import {canPickupDrop} from './campaign-pickups.mjs';
export function worldDropFrame(meta,item){if(item.type==='equipment'){const sheet=item.slot==='armor'?'armors':'weapons',index=(item.role==='melee'?0:6)+(item.quality||0);return {...meta.sheets[sheet].frames[index],sheet};}return meta.items[item.type];}
export function drawWorldDrops(c,w,art){const meta=art.dropMeta;if(!meta)return;const drops=w.campaign.drops||[],near=drops.filter(d=>canPickupDrop(w,d)).sort((a,b)=>Math.abs(a.x-w.player.x)-Math.abs(b.x-w.player.x))[0];for(const d of drops){if(d.picked)continue;const relic=relicFrame({wardRelic:'ward',springRelic:'spring'}[d.item.type]),f=relic?{...relic,anchor:relic.dropPivotLocal}:worldDropFrame(meta,d.item),img=relic?art.relics?.images[relic.file]:art['drop-'+f?.sheet];if(!f||!img)continue;const size=d.item.type==='equipment'?62:['health','mana'].includes(d.item.type)?48:55,scale=size/Math.max(f.rect[2],f.rect[3]),bob=Math.sin(w.fxTime*2+d.x)*2;c.save();c.globalAlpha=.17;c.fillStyle=d.item.type==='mana'?'#84c7f0':d.item.type==='health'?'#a4cc81':'#e2c78c';c.beginPath();c.ellipse(d.x,d.y-1,20,4,0,0,Math.PI*2);c.fill();c.globalAlpha=1;c.drawImage(img,...f.rect,d.x-f.anchor[0]*scale,d.y-6+bob-f.anchor[1]*scale,f.rect[2]*scale,f.rect[3]*scale);if(d===near){c.fillStyle='#fff1c6';c.font='12px "Microsoft YaHei"';c.textAlign='center';c.shadowColor='#05131b';c.shadowBlur=4;c.fillText('C拾取',d.x,d.y-size-15);}c.restore();}}
